source.css:
.stage {
  --bg: #0c0c0e; --ink: #edece7; --muted: #9c9b95; --accent: #ff003c; --accent-soft: #3a0a16; --surface: #121215;
  --paper: #0c0c0e; --paper2: #18181b; --line: #2a2a2f; --on: #f0efea; --on-muted: #9a9993; --stage-line: #2a2a2f; --shade: #3a3a40; --bag3: #222226;
  --space: #000000;
  --arrive: cubic-bezier(0.19, 1, 0.22, 1);
  --settle: cubic-bezier(0.22, 1, 0.36, 1);
  --pop: cubic-bezier(0.34, 1.56, 0.64, 1);
  --punch: cubic-bezier(0.175, 0.885, 0.32, 1.275);
  --exit: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --fall: cubic-bezier(0.55, 0, 1, 0.45);
  --rise-up: cubic-bezier(0, 0.55, 0.45, 1);
  --draw: cubic-bezier(0.215, 0.61, 0.355, 1);
  --travel: cubic-bezier(0.65, 0, 0.35, 1);
  position: absolute; inset: 0; overflow: hidden; background: var(--paper); color: var(--ink);
  font-family: roboto-mono, monospace; font-weight: 400;
}
.world, .scene, .in, .cam1, .cam2, .shk2, .lift2, .cam4, .cam6, .cam7, .field, .plunge, .shake, .path3, .crops, .slate { position: absolute; inset: 0; }

/* type: display + mono label */
.disp { position: absolute; margin: 0; font-family: anton, sans-serif; font-weight: 400; text-transform: uppercase; letter-spacing: -0.5px; line-height: 0.92; white-space: nowrap; color: var(--ink); }
.lab { position: absolute; margin: 0; font-family: roboto-mono, monospace; font-weight: 400; font-size: 34px; line-height: 1.2; letter-spacing: 4.8px; text-transform: uppercase; white-space: nowrap; color: var(--ink); }
.dkl { color: var(--on-muted); }
.chip { padding: 8px 16px; background: var(--paper); border: 2px solid var(--ink); }
.chip.red { background: var(--accent); border-color: var(--accent); color: var(--ink); }
.rec { display: inline-block; width: 16px; height: 16px; border-radius: 50%; background: var(--accent); margin-right: 16px; vertical-align: 4px; }

/* slate: 1px rule + label row */
.slate .rule { position: absolute; display: block; left: 115px; top: 96px; width: 1690px; height: 2px; background: var(--ink); transform-origin: left center; }
.slate .lab { left: 115px; top: 112px; }
.slate .kick { left: 1005px; width: 800px; text-align: right; }
.slate.dk .rule { background: var(--on-muted); }
.slate.dk .lab { color: var(--on); }

/* crop marks */
.cm { position: absolute; display: block; border-color: var(--ink); border-style: solid; border-width: 0; }
.cm.tl { border-top-width: 3px; border-left-width: 3px; } .cm.tr { border-top-width: 3px; border-right-width: 3px; }
.cm.bl { border-bottom-width: 3px; border-left-width: 3px; } .cm.br { border-bottom-width: 3px; border-right-width: 3px; }
.c7 .cm { border-color: var(--muted); }
.c7 .cm.bl, .c7 .cm.br { bottom: 96px !important; }

/* line-art rocket */
.pt { position: absolute; left: 0; top: 0; overflow: visible; }
.ln { fill: var(--paper); stroke: var(--ink); stroke-width: 4; stroke-linejoin: miter; }
.ln.ink { fill: var(--ink); } .ln.red { fill: var(--accent); } .paperf { fill: var(--paper); }
.hair { fill: none; stroke: var(--muted); stroke-width: 2; }
.lt { fill: none; stroke: var(--ink); stroke-width: 3; }
.mark { position: absolute; left: 95px; top: 118px; width: 110px; height: 110px; }
.rk { position: absolute; width: 300px; height: 640px; transform-origin: 150px 320px; }
.rk > div, .ign, .flick, .fire, .fire6 { position: absolute; inset: 0; }
.oct { position: absolute; overflow: visible; }
.oct .ln { vector-effect: non-scaling-stroke; }
.star { position: absolute; display: block; width: 3px; height: 3px; background: var(--on-muted); }
.lead { position: absolute; display: block; background: var(--ink); }
.ground { position: absolute; display: block; left: 0; top: 858px; width: 1920px; height: 3px; background: var(--ink); }
.groundf { position: absolute; display: block; left: 0; top: 861px; width: 1920px; height: 220px; background: var(--paper2); }
.pad { position: absolute; display: block; left: 790px; top: 840px; width: 340px; height: 18px; background: var(--ink); }

/* globe: ink fill, hairline wireframe */
.globe { position: absolute; overflow: visible; }
.gfill { fill: var(--ink); } .grim { fill: none; stroke: var(--on); stroke-width: 3; }
.gl { fill: none; stroke: var(--on-muted); stroke-width: 2; opacity: 0.55; }
.atmo { fill: none; stroke: var(--stage-line); stroke-width: 2; }

/* ---------- SC 01 LAUNCH, rear-left view 0 - 2.6 ---------- */
.s1 { background: var(--paper); animation: cut-off 0.01s step-end 2.6s both; }
.cam1 { transform-origin: 1104px 640px; animation: cam1 2.6s linear 0s both; }
.shk1 { position: absolute; inset: 0; animation: jitter 0.06s ease-in-out 1.2s 22 alternate both; }
.persp { position: absolute; left: 0; top: 0; overflow: visible; }
.tower { position: absolute; overflow: visible; }
.gnd { fill: var(--paper2); }
.road { fill: var(--paper); stroke: var(--ink); stroke-width: 2; }
.hz1 { fill: none; stroke: var(--ink); stroke-width: 2; }
.b2f { fill: var(--line); }
.ray { fill: none; stroke: var(--line); stroke-width: 3; }
.rays { animation: rays 2.6s var(--travel) 0s both; }
.sun { fill: var(--line); stroke: var(--ink); stroke-width: 3; }
.sunband { fill: none; stroke: var(--paper); stroke-width: 16; }
.ridgefar { fill: var(--line); stroke: var(--ink); stroke-width: 2; stroke-linejoin: miter; }
.ridgenear { fill: var(--bag3); stroke: var(--ink); stroke-width: 2; stroke-linejoin: miter; }
.cloud2 { position: absolute; overflow: visible; }
.cloudf { fill: var(--paper); stroke: var(--ink); stroke-width: 2.5; stroke-linejoin: round; }
.curl { fill: none; stroke: var(--muted); stroke-width: 2; stroke-linecap: round; }
.cl0, .cl1 { animation: drift-a 2.6s var(--travel) 0s both; }
.cl2, .cl3 { animation: drift-b 2.6s var(--travel) 0s both; }
.beamf { fill: var(--on-muted); stroke: var(--muted); stroke-width: 1.5; opacity: 0.16; }
.bm0 { animation: sweep-a 0.65s ease-in-out 0s 4 alternate both; }
.bm1 { animation: sweep-b 0.8s ease-in-out 0s 3 alternate both; }
.bm2 { animation: sweep-b 0.65s ease-in-out 0.1s 3 alternate both; }
.ring { fill: none; stroke: var(--ink); stroke-width: 2; vector-effect: non-scaling-stroke; opacity: 0; }
.rg0 { animation: shock 1s var(--settle) 1.05s both; }
.rg1 { animation: shock 1s var(--settle) 1.3s both; }
.rg2 { animation: shock 1s var(--settle) 1.55s both; }
.wing { fill: none; stroke: var(--ink); stroke-width: 3; stroke-linejoin: miter; }
.bird { animation: flee 1.4s cubic-bezier(0.3, 0, 0.6, 1) 1.05s both; }
.bd1 { animation-delay: 1.1s; } .bd2 { animation-delay: 1.15s; } .bd3 { animation-delay: 1.08s; } .bd4 { animation-delay: 1.18s; } .bd5 { animation-delay: 1.12s; }
.r1 { transform-origin: 150px 500px; transform: scale(0.7); }
.arm1 { position: absolute; display: block; width: 54px; height: 14px; background: var(--paper); border: 4px solid var(--ink);
  transform-origin: right center; animation: arm-away 0.5s var(--settle) 0.6s both; }
.lift1, .wrapmark { position: absolute; inset: 0; }
.strip { position: absolute; overflow: hidden; }
.strip img { position: absolute; }
.shade { mix-blend-mode: screen; }
.sh1 { fill: var(--paper2); } .sh2 { fill: var(--line); }
.r3d .sh1 { fill: var(--line); } .r3d .sh2 { fill: var(--shade); }
.ol { fill: none; stroke: var(--ink); stroke-width: 4; stroke-linejoin: round; }
.seam { fill: none; stroke: var(--muted); stroke-width: 2; }
.lift1 { transform-origin: 150px 500px; animation: lift1 0.95s cubic-bezier(0.4, 0, 0.85, 0.55) 1.55s both; }
.s1 .ign { transform-origin: 150px 500px; animation: ignite 0.3s var(--pop) 1.0s both; }
.s1 .flick { transform-origin: 150px 500px; animation: flick 0.08s ease-in-out 1.15s 18 alternate both; }

/* ---------- SC 02 IGNITION 2.6 - 4.8: the launch-pov rocket climbs, sheds boosters, then its body ---------- */
.s2 { animation: cut-off 0.01s step-end 6s both; }
.s2 .in { opacity: 0; background: var(--paper); animation: cut-on 0.01s step-end 2.6s both; }
.cam2 { transform-origin: 960px 540px; animation: push7 3.4s var(--travel) 2.6s both; }
.r2b { left: 810px; top: 100px; transform-origin: 150px 300px; transform: scale(1.15); }
.climb, .b2far, .b2near, .mfl, .whole, .halfL, .halfR, .soloe, .bfl, .hc { position: absolute; inset: 0; }
.climb { animation: climb 0.8s var(--settle) 2.6s both; }
.s2 .flick { transform-origin: 150px 510px; animation: flick 0.08s ease-in-out 2.6s 26 alternate both; }
.b2near { transform-origin: 42px 390px; animation: drop-near 1s var(--fall) 3.3s both; }
.b2far { transform-origin: 260px 390px; animation: drop-far 1s var(--fall) 3.34s both; }
.b2near .bfl { transform-origin: 42px 500px; animation: shrink 0.2s var(--exit) 3.3s both; }
.b2far .bfl { transform-origin: 260px 500px; animation: shrink 0.2s var(--exit) 3.34s both; }
.mfl { transform-origin: 150px 510px; animation: shrink 0.2s var(--exit) 3.8s both; }
.whole { animation: cut-off 0.01s step-end 3.8s both; }
.halfL { opacity: 0; clip-path: inset(0 150px 0 0); transform-origin: 100px 300px; animation: cut-on 0.01s step-end 3.8s both, split-l 1s var(--fall) 3.8s both; }
.halfR { opacity: 0; clip-path: inset(0 0 0 150px); transform-origin: 200px 300px; animation: cut-on 0.01s step-end 3.8s both, split-r 1s var(--fall) 3.8s both; }
.soloe { opacity: 0; animation: cut-on 0.01s step-end 3.8s both; }
.split { stroke-width: 8; }
.rays2 { transform-origin: 960px 1300px; animation: rays 3.4s var(--travel) 2.6s both; }
.fc { animation: cloud-far 1.4s cubic-bezier(0.4, 0, 0.8, 0.6) 2.6s both; }
.nc0 { animation: cloud-near 0.7s cubic-bezier(0.4, 0, 0.8, 0.6) 2.7s both; }
.nc1 { animation: cloud-near 0.7s cubic-bezier(0.4, 0, 0.8, 0.6) 3s both; }
.nc2 { animation: cloud-near 0.7s cubic-bezier(0.4, 0, 0.8, 0.6) 3.3s both; }
.earth2 { animation: earth-away 1.5s var(--travel) 2.6s both; }
.gfill2 { fill: var(--paper2); stroke: var(--ink); stroke-width: 3; }
.atm { fill: none; stroke: var(--line); stroke-width: 3; }
.space2 { position: absolute; inset: 0; opacity: 0; animation: space-in 1.1s var(--travel) 3.3s both; }
.stars2w { position: absolute; inset: 0; opacity: 0; animation: space-in 0.8s var(--travel) 3.9s both; }
.spblock { position: absolute; display: block; inset: 0; background: var(--space); }
.star-dot { position: absolute; display: block; width: 3px; height: 3px; background: var(--on-muted); }
.sp2 { position: absolute; display: block; top: -300px; width: 3px; height: 220px; background: var(--muted); }
.sp2-0, .sp2-4 { animation: line-down2 0.3s cubic-bezier(0.3, 0, 0.7, 1) 2.7s 4 both; }
.sp2-1, .sp2-5 { animation: line-down2 0.3s cubic-bezier(0.3, 0, 0.7, 1) 2.78s 4 both; }
.sp2-2, .sp2-6 { animation: line-down2 0.3s cubic-bezier(0.3, 0, 0.7, 1) 2.86s 4 both; }
.sp2-3, .sp2-7 { animation: line-down2 0.3s cubic-bezier(0.3, 0, 0.7, 1) 2.94s 4 both; }
.word2 { left: 160px; top: 578px; width: 1600px; text-align: center; font-size: 86px; letter-spacing: 6px; color: var(--on); animation: rise 0.6s var(--arrive) 4.8s both; }
.flate { position: absolute; left: 49px; top: 228px; width: 210px; height: 210px; transform-origin: 105px 105px; animation: e-free 0.45s var(--pop) 3.8s both; }

/* ---------- SC 03 RE-ENTRY 6.0 - 7.5: only the Elah mark, falling on paper ---------- */
.s5 { animation: cut-off 0.01s step-end 7.5s both; }
.s5 .in { opacity: 0; background: var(--paper); animation: cut-on 0.01s step-end 6s both; }
.fall5 { position: absolute; left: 810px; top: 330px; width: 300px; height: 300px; animation: fall5 1.5s linear 6s both; }
.sway5 { position: absolute; inset: 0; animation: sway5 0.375s ease-in-out 6s 4 alternate both; }
.spin5 { position: absolute; inset: 0; transform-origin: 150px 150px; animation: wobble5 0.25s ease-in-out 6s 6 alternate both; }
.wd { position: absolute; display: block; top: 1100px; }
.air { position: absolute; display: block; top: 560px; width: 2px; height: 120px; background: var(--muted); }
.gust { position: absolute; overflow: visible; }
.gpath { fill: none; stroke: var(--ink); stroke-width: 2.5; stroke-linecap: butt; stroke-dasharray: 0.45 1; stroke-dashoffset: 0.45; }
.dark5 { position: absolute; inset: 0; animation: space-out 0.8s var(--travel) 6.35s both; }
.stars5 { position: absolute; left: 0; top: 0; width: 1920px; height: 1500px; animation: stars-up 1.2s cubic-bezier(0.4, 0, 0.8, 0.6) 6s both; }
.e5img { position: absolute; left: 0; top: 0; width: 300px; height: 300px; }

/* ---------- SC 04 TOUCHDOWN 7.5 - 13.7: the Elah mark settles onto borderless bean bags, then the news ---------- */
.s6 .in { opacity: 0; background: var(--paper); animation: cut-on 0.01s step-end 7.5s both; }
.cam6 { transform-origin: 960px 640px; animation: push6 6.2s var(--travel) 7.5s both; }
.bean-bag { position: absolute; display: block; border-radius: 50% 50% 46% 46% / 62% 62% 38% 38%; }
.bean-bag img { position: absolute; }
.t1 { background: var(--paper2); } .t2 { background: var(--line); } .t3 { background: var(--bag3); }
.dip { transform-origin: 50% 100%; animation: dip 2s linear 7.55s both; }
.land6 { position: absolute; left: 830px; top: 450px; width: 260px; height: 260px; animation: land6 2s linear 7.55s both; }
.rock6 { position: absolute; inset: 0; transform-origin: 130px 200px; animation: rock6 2s linear 7.55s both; }
.sq6 { position: absolute; inset: 0; transform-origin: 130px 250px; animation: sq6 2s linear 7.55s both; }
.e6img { position: absolute; left: 0; top: 0; width: 260px; height: 260px; }
.air6 { position: absolute; overflow: visible; transform-origin: 200px 100px; }
.wisp { fill: none; stroke: var(--ink); stroke-width: 3; stroke-linecap: round; }
.bub { fill: var(--paper); stroke: var(--ink); stroke-width: 2.5; }
.pl, .prr { opacity: 0; }
.ap0 .pl, .ap0 .prr { animation: puff-out 0.55s var(--settle) 8.1s both; }
.ap1 .pl, .ap1 .prr { animation: puff-out 0.5s var(--settle) 8.76s both; }
.ap2 .pl, .ap2 .prr { animation: puff-out 0.45s var(--settle) 9.16s both; }
.ap3 .pl, .ap3 .prr { animation: puff-out 0.4s var(--settle) 9.4s both; }
.wh { position: absolute; display: block; top: -170px; width: 3px; height: 110px; background: var(--muted); opacity: 0; animation: whoosh 0.5s linear 7.6s both; }
.wh0 { left: -50px; top: -60px; height: 170px; } .wh1 { left: 300px; top: -30px; height: 140px; } .wh2 { left: 340px; top: 40px; height: 100px; }
.msg { left: 160px; width: 1600px; text-align: center; font-size: 86px; color: var(--ink); }
.m1 { top: 100px; animation: rise 0.6s var(--arrive) 9.55s both; }
.m2 { top: 200px; animation: rise 0.6s var(--arrive) 9.65s both; }
.selw { position: relative; display: inline-block; margin: 0 16px; }
.lock6 { position: absolute; left: 836px; top: 318px; width: 248px; height: 80px; animation: rise 0.6s var(--arrive) 10.5s both; }
.l6m { position: absolute; left: 0; top: 0; width: 80px; height: 80px; }
.l6x { left: 104px; top: 6px; width: 40px; text-align: center; font-size: 54px; line-height: 1.2; letter-spacing: 0; color: var(--muted); }
.l6c { position: absolute; left: 168px; top: 0; width: 80px; height: 80px; }
.selbox { position: absolute; display: block; left: -12px; right: -12px; top: 2px; bottom: -2px; border: 3px solid var(--accent); animation: sel-in 0.35s var(--settle) 10.2s both; }
.h { position: absolute; display: block; width: 14px; height: 14px; background: var(--paper); border: 3px solid var(--accent); }
.hl1 { left: -10px; top: -10px; } .hl2 { right: -10px; top: -10px; } .hl3 { left: -10px; bottom: -10px; } .hl4 { right: -10px; bottom: -10px; }

@keyframes cut-on { from { opacity: 0; } to { opacity: 1; } }
@keyframes cut-off { from { opacity: 1; } to { opacity: 0; } }
@keyframes rise { from { opacity: 0; transform: translateY(40px); } to { opacity: 1; transform: translateY(0); } }
@keyframes rays { from { transform: rotate(0deg); } to { transform: rotate(6deg); } }
@keyframes drift-a { from { transform: translateX(0); } to { transform: translateX(-70px); } }
@keyframes drift-b { from { transform: translateX(0); } to { transform: translateX(50px); } }
@keyframes sweep-a { from { transform: rotate(-16deg); } to { transform: rotate(10deg); } }
@keyframes sweep-b { from { transform: rotate(14deg); } to { transform: rotate(-12deg); } }
@keyframes shock { 0% { opacity: 0.9; transform: scale(1); } 100% { opacity: 0; transform: scale(4.2); } }
@keyframes flee { 0% { transform: translate(0, 0) scale(1, 1); } 25% { transform: translate(-60px, -70px) scale(1, 0.4); } 50% { transform: translate(-150px, -150px) scale(1, 1); } 75% { transform: translate(-250px, -220px) scale(1, 0.4); } 100% { transform: translate(-360px, -300px) scale(1, 1); } }
@keyframes arm-away { from { transform: rotate(0deg); } to { transform: rotate(88deg); } }
@keyframes cloud-far { from { transform: translateY(0); } to { transform: translateY(1300px); } }
@keyframes cloud-near { from { transform: translateY(0); } to { transform: translateY(1500px); } }
@keyframes earth-away { from { transform: translateY(0); } to { transform: translateY(900px); } }
@keyframes space-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes stars-up { from { transform: translateY(0); } to { transform: translateY(-420px); } }
@keyframes space-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes line-down2 { 0% { opacity: 0; transform: translateY(0); } 20% { opacity: 0.8; } 100% { opacity: 0; transform: translateY(1500px); } }
@keyframes climb { from { transform: translateY(760px); } to { transform: translateY(0); } }
@keyframes drop-near { from { transform: translate(0, 0) rotate(0deg); } to { transform: translate(-150px, 780px) rotate(-28deg); } }
@keyframes drop-far { from { transform: translate(0, 0) rotate(0deg); } to { transform: translate(150px, 760px) rotate(26deg); } }
@keyframes split-l { from { transform: translate(0, 0) rotate(0deg); } to { transform: translate(-260px, 1050px) rotate(-24deg); } }
@keyframes split-r { from { transform: translate(0, 0) rotate(0deg); } to { transform: translate(260px, 1050px) rotate(24deg); } }
@keyframes e-free { from { transform: scale(0.82, 1); } to { transform: scale(1, 1); } }
@keyframes puff-out { 0% { opacity: 0; transform: translate(0, 0) scale(0.6); } 15% { opacity: 1; } 100% { opacity: 0; transform: translate(-90px, -18px) scale(1.15); } }
@keyframes whoosh { 0% { opacity: 0; } 20% { opacity: 0.8; } 90% { opacity: 0.8; } 100% { opacity: 0; } }
@keyframes land6 {
  0% { transform: translateY(-820px); animation-timing-function: cubic-bezier(0.333, 0, 0.667, 0.333); }
  27.5% { transform: translateY(0); animation-timing-function: cubic-bezier(0.333, 0.667, 0.667, 1); }
  44% { transform: translateY(-295px); animation-timing-function: cubic-bezier(0.333, 0, 0.667, 0.333); }
  60.5% { transform: translateY(0); animation-timing-function: cubic-bezier(0.333, 0.667, 0.667, 1); }
  70.4% { transform: translateY(-106px); animation-timing-function: cubic-bezier(0.333, 0, 0.667, 0.333); }
  80.3% { transform: translateY(0); animation-timing-function: cubic-bezier(0.333, 0.667, 0.667, 1); }
  86.2% { transform: translateY(-38px); animation-timing-function: cubic-bezier(0.333, 0, 0.667, 0.333); }
  92.1%, 100% { transform: translateY(0); }
}
@keyframes rock6 {
  0%, 27.5% { transform: rotate(10deg); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  44%, 60.5% { transform: rotate(-6deg); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  70.4%, 80.3% { transform: rotate(3deg); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  86.2% { transform: rotate(-1deg); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  92.1%, 100% { transform: rotate(0deg); }
}
@keyframes sq6 {
  0% { transform: scale(1, 1); animation-timing-function: cubic-bezier(0.333, 0, 0.667, 0.333); }
  25.5% { transform: scale(0.94, 1.08); animation-timing-function: ease-out; }
  27.5% { transform: scale(1.2, 0.76); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  31% { transform: scale(0.95, 1.06); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  35%, 58.5% { transform: scale(1, 1); animation-timing-function: ease-out; }
  60.5% { transform: scale(1.12, 0.86); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  64% { transform: scale(0.97, 1.03); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  67%, 79.3% { transform: scale(1, 1); animation-timing-function: ease-out; }
  80.3% { transform: scale(1.07, 0.92); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  83%, 91.3% { transform: scale(1, 1); animation-timing-function: ease-out; }
  92.1% { transform: scale(1.03, 0.96); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  95%, 100% { transform: scale(1, 1); }
}
@keyframes dip {
  0%, 26.5% { transform: scale(1, 1); animation-timing-function: ease-out; }
  29% { transform: scale(1.06, 0.82); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  37%, 60% { transform: scale(1, 1); animation-timing-function: ease-out; }
  62% { transform: scale(1.04, 0.9); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  68%, 79.8% { transform: scale(1, 1); animation-timing-function: ease-out; }
  81.5% { transform: scale(1.02, 0.95); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  86%, 91.8% { transform: scale(1, 1); animation-timing-function: ease-out; }
  93.2% { transform: scale(1.01, 0.98); animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1); }
  97%, 100% { transform: scale(1, 1); }
}
@keyframes fall5 {
  0% { transform: translateY(-620px); animation-timing-function: cubic-bezier(0.5, 0, 1, 0.6); }
  9% { transform: translateY(0); animation-timing-function: cubic-bezier(0.45, 0, 0.55, 1); }
  46% { transform: translateY(46px); animation-timing-function: cubic-bezier(0.45, 0, 0.55, 1); }
  82% { transform: translateY(-10px); animation-timing-function: cubic-bezier(0.55, 0, 1, 0.5); }
  100% { transform: translateY(900px); }
}
@keyframes sway5 { from { transform: translateX(-48px); } to { transform: translateX(48px); } }
@keyframes wobble5 { from { transform: rotate(-14deg); } to { transform: rotate(12deg); } }
@keyframes wind-up { 0% { opacity: 0; transform: translateY(0); } 15% { opacity: 1; } 85% { opacity: 1; } 100% { opacity: 0; transform: translateY(-1400px); } }
@keyframes air-up { 0% { opacity: 0; transform: translateY(0); } 20% { opacity: 0.9; } 100% { opacity: 0; transform: translateY(-420px); } }
@keyframes gust { from { stroke-dashoffset: 0.45; } to { stroke-dashoffset: -1; } }
@keyframes cam1 {
  0% { transform: translateY(0) scale(1); animation-timing-function: var(--travel); }
  60% { transform: translateY(0) scale(1.05); animation-timing-function: var(--travel); }
  100% { transform: translateY(150px) scale(1.05); }
}
@keyframes lift1 { from { transform: translate(0, 0) scale(1) rotate(0deg); } to { transform: translate(90px, -760px) scale(0.75) rotate(8deg); } }

@keyframes push6 { from { transform: scale(1); } to { transform: scale(1.05); } }
@keyframes push7 { from { transform: scale(1); } to { transform: scale(1.02); } }
@keyframes jitter { from { transform: translate(-4px, 0); } to { transform: translate(4px, 2px); } }
@keyframes ignite { from { transform: scale(0); } to { transform: scale(1); } }
@keyframes flick { from { transform: scale(1, 1); } to { transform: scale(1.04, 1.16); } }
@keyframes shrink { from { transform: scale(1); } to { transform: scale(0); } }
@keyframes sel-in { from { opacity: 0; transform: scale(1.06); } to { opacity: 1; transform: scale(1); } }

